 for(let col=0;col<Math.max(2,Math.floor(w/62));col++){let wx=x+22+col*58,wy=base-h+46;ctx.fillStyle='#0a1119';ctx.fillRect(wx,wy,12,24);ctx.beginPath();ctx.arc(wx+6,wy,6,Math.PI,0);ctx.fill();ctx.fillRect(wx+5,wy+12,2,12);ctx.fillStyle=light+'88';ctx.fillRect(wx+2,wy+12,3,5)}
