function drawEnemies(){for(const e of enemies[room])if(e.alive){ctx.save();let bob=e.kind==='slime'?Math.sin(elapsed*5+e.x)*2:Math.sin(elapsed*2+e.x)*.8;ctx.translate(e.x+15,e.y+20+bob);if(e.dir<0)ctx.scale(-1,1);drawGlow(0,0,e.kind==='slime'?25:30,e.kind==='slime'?'#93d79a':e.kind==='skeleton'?'#d8cba3':'#9b615c');
 if(e.kind==='slime'){
  let squash=1+Math.sin(elapsed*6+e.x)*.08;ctx.scale(1/squash,squash);ctx.fillStyle='#547d61';ctx.beginPath();ctx.moveTo(-16,9);ctx.quadraticCurveTo(-15,-8,-7,-13);ctx.quadraticCurveTo(0,-20,8,-11);ctx.quadraticCurveTo(16,-5,16,9);ctx.quadraticCurveTo(1,17,-16,9);ctx.fill();ctx.fillStyle='#8cbd7d';ctx.beginPath();ctx.ellipse(-3,-9,7,3,-.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#1b302c';ctx.fillRect(-7,-3,3,4);ctx.fillRect(5,-3,3,4);ctx.fillStyle='#d0d796';ctx.fillRect(-6,-3,1,1);ctx.fillRect(6,-3,1,1);ctx.fillStyle='#435b4e';ctx.beginPath();ctx.ellipse(0,11,12,3,0,0,Math.PI*2);ctx.fill();
 }else if(e.kind==='skeleton'){
  ctx.fillStyle='#d4c8ad';ctx.fillRect(-7,-7,14,17);ctx.fillStyle='#eee2c3';ctx.beginPath();ctx.arc(0,-12,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#222630';ctx.beginPath();ctx.ellipse(-4,-12,2.4,3.8,0,0,Math.PI*2);ctx.ellipse(4,-12,2.4,3.8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#aa9d82';ctx.fillRect(-4,-5,8,2);ctx.strokeStyle='#b9ad92';ctx.lineWidth=2;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(-7,-3+i*3);ctx.quadraticCurveTo(0,-1+i*3,7,-3+i*3);ctx.stroke()}ctx.strokeStyle='#d4c8ad';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-5,9);ctx.lineTo(-9,17);ctx.moveTo(5,9);ctx.lineTo(8,17);ctx.moveTo(-8,-1);ctx.lineTo(-14,5);ctx.lineTo(-13,11);ctx.moveTo(8,-1);ctx.lineTo(14,3);ctx.stroke();ctx.strokeStyle='#8b7b62';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(13,5);ctx.lineTo(19,-17);ctx.stroke();ctx.fillStyle='#c2b28f';ctx.beginPath();ctx.moveTo(19,-20);ctx.lineTo(22,-12);ctx.lineTo(16,-12);ctx.fill();
